[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#required-element-usage]

#### Required Element Usage

```tsx
// Page landmark regions — required for screen reader navigation
export function AppLayout({ children }: { children: React.ReactNode }) {
  return (
    <>
      <a href="#main-content" className="sr-only focus:not-sr-only focus:absolute focus:p-2 focus:z-50">
        Skip to main content
      </a>
      <header role="banner">
        <nav aria-label="Primary navigation">
          {/* navigation items */}
        </nav>
      </header>
      <main id="main-content" tabIndex={-1}>
        {children}
      </main>
      <footer role="contentinfo">
        {/* footer content */}
      </footer>
    </>
  );
}
```

