page_texts.21:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#form-label-association]

#### Form Label Association

```tsx
// ✅ Associate every input with its label via htmlFor/id
export function MemberIdInput({
  value,
  onChange,
  error,
}: {
  value: string;
  onChange: (v: string) => void;
  error?: string;
}) {
  const inputId = 'member-id-input';
  const errorId = 'member-id-error';

  return (
    <div>
      <label htmlFor={inputId} className="block text-sm font-medium">
        Member ID
      </label>
      <input
        id={inputId}
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-describedby={error ? errorId : undefined}
        aria-invalid={error ? 'true' : undefined}
        className="mt-1 block w-full rounded-md border px-3 py-2"
      />
      {error && (
        <p id={errorId} role="alert" className="mt-1 text-sm text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}
```

