page_texts.26:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#custom-keyboard-handler-example]

#### Custom Keyboard Handler Example

When building a custom component that requires keyboard handling beyond a native element:

```tsx
// ✅ Custom listbox item — arrow key navigation within a group
export function ListboxOption({
  value,
  children,
  onSelect,
}: {
  value: string;
  children: React.ReactNode;
  onSelect: (v: string) => void;
}) {
  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelect(value);
    }
  }

  return (
    <div
      role="option"
      tabIndex={0}
      aria-selected={false}
      onKeyDown={handleKeyDown}
      onClick={() => onSelect(value)}
      className="cursor-pointer px-3 py-2 hover:bg-muted focus:bg-muted focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {children}
    </div>
  );
}
```

page_texts.27:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#roving-tabindex-for-toolbars-and-tab-groups]

#### Roving tabIndex for Toolbars and Tab Groups

```tsx
// ✅ Roving tabIndex pattern — only one element in the group is in the tab order at a time
export function ToolbarGroup({ items }: { items: ToolbarItem[] }) {
  const [activeIndex, setActiveIndex] = React.useState(0);
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);

  function handleKeyDown(e: React.KeyboardEvent, index: number) {
    let next = index;
    if (e.key === 'ArrowRight') next = (index + 1) % items.length;
    if (e.key === 'ArrowLeft') next = (index - 1 + items.length) % items.length;
    if (e.key === 'Home') next = 0;
    if (e.key === 'End') next = items.length - 1;
    if (next !== index) {
      e.preventDefault();
      setActiveIndex(next);
      refs.current[next]?.focus();
    }
  }

  return (
    <div role="toolbar" aria-label="Claim actions">
      {items.map((item, index) => (
        <button
          key={item.id}
          ref={(el) => { refs.current[index] = el; }}
          tabIndex={index === activeIndex ? 0 : -1}
          onKeyDown={(e) => handleKeyDown(e, index)}
          onClick={item.action}
          type="button"
          className="px-3 py-1 focus-visible:ring-2 focus-visible:ring-ring"
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}
```

