page_texts.30:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#focus-trap-in-dialogs]

#### Focus Trap in Dialogs

Radix UI `Dialog` handles focus trapping natively. When using Shadcn/UI `Dialog`, do not render the dialog conditionally in a way that destroys the trap:

```tsx
// ✅ Let Radix Dialog manage focus trap — do not use conditional rendering that bypasses it
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';

export function ConfirmDeleteDialog({
  open,
  onOpenChange,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Confirm Deletion</DialogTitle>
        </DialogHeader>
        <p>This action cannot be undone. Delete this record?</p>
        <div className="flex justify-end gap-2 pt-4">
          <button type="button" onClick={() => onOpenChange(false)}>
            Cancel
          </button>
          <button type="button" onClick={onConfirm} className="bg-destructive text-destructive-foreground">
            Delete
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
```

page_texts.31:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#focus-restoration-after-dynamic-state-changes]

#### Focus Restoration After Dynamic State Changes

```tsx
// ✅ Restore focus to the trigger after a panel or popover closes
export function FilterPopover() {
  const [open, setOpen] = React.useState(false);
  const triggerRef = React.useRef<HTMLButtonElement>(null);

  function handleClose() {
    setOpen(false);
    // Radix Popover restores focus automatically; document this as the expected behavior
    // For custom non-Radix panels, manually restore:
    // triggerRef.current?.focus();
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger ref={triggerRef} asChild>
        <button type="button">Open filters</button>
      </PopoverTrigger>
      <PopoverContent>
        {/* filter controls */}
        <button type="button" onClick={handleClose}>Apply</button>
      </PopoverContent>
    </Popover>
  );
}
```

page_texts.32:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#programmatic-focus-for-route-changes]

#### Programmatic Focus for Route Changes

```tsx
// ✅ Move focus to the page heading or main content region on client-side navigation
// In Next.js App Router, use a layout component:
'use client';

import { usePathname } from 'next/navigation';

export function RouteAnnouncerLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const mainRef = React.useRef<HTMLElement>(null);

  React.useEffect(() => {
    mainRef.current?.focus();
  }, [pathname]);

  return (
    <main ref={mainRef} id="main-content" tabIndex={-1} className="outline-none">
      {children}
    </main>
  );
}
```

