[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#unit-test-integration-vitest--react-testing-library]

#### Unit Test Integration (Vitest + React Testing Library)

Install jest-axe (works with Vitest via vitest-axe or direct axe-core usage):

```bash
npm install --save-dev axe-core @axe-core/react vitest-axe
```

```typescript
// src/components/ui/__tests__/button.test.tsx
import { render } from '@testing-library/react';
import { axe, toHaveNoViolations } from 'vitest-axe';
import { expect, test } from 'vitest';
import { Button } from '../button';

expect.extend(toHaveNoViolations);

test('Button has no accessibility violations', async () => {
  const { container } = render(<Button>Submit Claim</Button>);
  const results = await axe(container);
  expect(results).toHaveNoViolations();
});

test('Button with icon has accessible label', async () => {
  const { container } = render(
    <Button>
      <TrashIcon aria-hidden="true" />
      <span>Delete record</span>
    </Button>
  );
  const results = await axe(container);
  expect(results).toHaveNoViolations();
});
```

page_texts.35:
[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#integration-test-playwright--axe-core]

#### Integration Test (Playwright + axe-core)

```typescript
// e2e/accessibility/claim-form.spec.ts
import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

test.describe('Claim Submission Form accessibility', () => {
  test('has no WCAG 2.2 AA violations on initial load', async ({ page }) => {
    await page.goto('/claims/new');

    const results = await new AxeBuilder({ page })
      .withTags(['wcag2a', 'wcag2aa', 'wcag22aa'])
      .analyze();

    expect(results.violations).toEqual([]);
  });

  test('error messages are associated with inputs', async ({ page }) => {
    await page.goto('/claims/new');
    await page.getByRole('button', { name: 'Submit' }).click();

    const results = await new AxeBuilder({ page })
      .withTags(['wcag2a', 'wcag2aa', 'wcag22aa'])
      .analyze();

    expect(results.violations).toEqual([]);
  });
});
```

