[strategy/guidance/application/accessibility/GUID-APP-ACC-001-accessible-component-implementation-guidance.md#use-case-2--accessible-toast--notification]

### Use Case 2 — Accessible Toast / Notification

```tsx
// Accessible toast using Radix Toast + aria-live
import * as Toast from '@radix-ui/react-toast';

export function ClaimNotification({ message, type }: { message: string; type: 'success' | 'error' }) {
  return (
    <Toast.Provider swipeDirection="right">
      <Toast.Root
        // Radix Toast uses aria-live="polite" by default; use "assertive" for errors
        aria-live={type === 'error' ? 'assertive' : 'polite'}
        aria-atomic="true"
        className="rounded-md bg-background p-4 shadow-lg"
      >
        <Toast.Title className={cn('font-semibold', type === 'error' && 'text-destructive')}>
          {type === 'success' ? 'Success' : 'Error'}
        </Toast.Title>
        <Toast.Description>{message}</Toast.Description>
        <Toast.Action asChild altText="Dismiss notification">
          <button type="button">Dismiss</button>
        </Toast.Action>
      </Toast.Root>
      <Toast.Viewport className="fixed bottom-4 right-4 flex flex-col gap-2" />
    </Toast.Provider>
  );
}
```

